require_once __DIR__.'/../../config/conexion.php';require_once __DIR__.'/../Models/PlanillaAjusteModel.php';require_once __DIR__.'/../Models/PlanillaAjusteConsultaModel.php';class PlanillaAjusteController{private function m(){global $conexion;return new PlanillaAjusteModel($conexion);}function index():void{autorizar('planilla.calcular');global $conexion;try{extract((new PlanillaAjusteConsultaModel($conexion))->datos((int)($_GET['id']??0)));}catch(Throwable $e){mensaje('error',$e->getMessage());header('Location:index.php?url=planilla');exit;}require __DIR__.'/../Views/layouts/header.php';require __DIR__.'/../Views/layouts/navbar.php';require __DIR__.'/../Views/planilla/ajustes.php';require __DIR__.'/../Views/layouts/footer.php';}function guardar():void{autorizar('planilla.calcular');validarCsrf();$periodo=(int)($_POST['id_periodo_pago']??0);try{$this->m()->guardar($_POST,(int)$_SESSION['usuario']['id_usuario']);mensaje('success','Ajuste agregado al borrador.');}catch(Throwable $e){mensaje('error',$e->getMessage());}header('Location:index.php?url=planilla_ajustes&id='.$periodo);exit;}function anular():void{autorizar('planilla.calcular');validarCsrf();$periodo=(int)($_POST['id_periodo_pago']??0);try{$periodo=$this->m()->anular((int)($_POST['id_ajuste']??0),$_POST['motivo_anulacion']??'',(int)$_SESSION['usuario']['id_usuario']);mensaje('success','Ajuste anulado correctamente.');}catch(Throwable $e){mensaje('error',$e->getMessage());}header('Location:index.php?url=planilla_ajustes&id='.$periodo);exit;}}
